    "speaker": "ROSTOVA",
    "lang": "es",
    "filename": "mission_leo_bionutrients_cml_3_astra_hint_1.mp3",
    "canonicalText": "La incubadora biológica consume 18W activa. Revisa que el margen de energía se mantenga sobre 35%."
